<?php
declare(strict_types=1); require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/auth.php';require_once __DIR__.'/../../src/config.php';require_admin();$checks=[];
try{$t=microtime(true);$v=db()->query('SELECT 1')->fetchColumn();$checks[]=['name'=>'PostgreSQL','ok'=>$v==1,'detail'=>number_format((microtime(true)-$t)*1000,1).' ms'];}catch(Throwable $e){$checks[]=['name'=>'PostgreSQL','ok'=>false,'detail'=>$e->getMessage()];}
foreach([['N8N_API_KEY',env('N8N_API_KEY')],['N8N Web Teacher',env('N8N_WEB_TEACHER_URL')],['OpenAI',env('OPENAI_API_KEY')]] as [$n,$v])$checks[]=['name'=>$n,'ok'=>(bool)$v,'detail'=>$v?'Configurado':'Não configurado'];
$stats=['users'=>(int)db()->query('SELECT COUNT(*) FROM app_users')->fetchColumn(),'students'=>(int)db()->query('SELECT COUNT(*) FROM students')->fetchColumn(),'failed'=>(int)db()->query("SELECT COUNT(*) FROM login_attempts WHERE success=false AND created_at>=NOW()-INTERVAL '24 hours'")->fetchColumn()];
$recent=db()->query("SELECT al.action,al.entity_type,al.entity_id,al.ip_address,al.created_at,u.name user_name FROM audit_logs al LEFT JOIN app_users u ON u.id=al.user_id ORDER BY al.created_at DESC LIMIT 30")->fetchAll();$pageTitle='Saúde do sistema';require __DIR__.'/../../templates/header.php';?>
<section class="cards"><div class="card"><div class="label">Usuários</div><div class="metric"><?=$stats['users']?></div></div><div class="card"><div class="label">Alunos</div><div class="metric"><?=$stats['students']?></div></div><div class="card"><div class="label">Falhas de login — 24h</div><div class="metric"><?=$stats['failed']?></div></div></section><section class="panel"><h2>Verificações</h2><div class="grid-3"><?php foreach($checks as $c):?><div class="list-card"><span class="badge <?=$c['ok']?'success':'danger'?>"><?=$c['ok']?'OK':'Falha'?></span><h3><?=htmlspecialchars($c['name'])?></h3><p><?=htmlspecialchars($c['detail'])?></p></div><?php endforeach;?></div></section><section class="panel" style="margin-top:20px"><h2>Auditoria recente</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>IP</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=date('d/m/Y H:i:s',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($r['user_name']??'Sistema/legado')?></td><td><span class="badge"><?=htmlspecialchars($r['action'])?></span></td><td><?=htmlspecialchars(trim(($r['entity_type']??'').' '.($r['entity_id']??'')))?></td><td><?=htmlspecialchars($r['ip_address']??'-')?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../templates/footer.php';?>
